def choose_move(observation):
    # Defensive defaults
    # Try to read a simple "best guess" from observation if present; otherwise default to stay.
    # We assume the environment uses typical grid signals: "own_pos", "goals", "enemies", "resources", "territory".
    # Compute a small heuristic: move toward nearest resource, or toward nearest goal point, or toward center if nothing.
    ox = observation.get("own_pos", (0, 0))
    gx = observation.get("goal_pos", None)
    resources = observation.get("resources", [])
    enemies = observation.get("enemies", [])
    territory_center = observation.get("center", (0, 0))
    # Normalize to integers
    ox_x, ox_y = int(ox[0]), int(ox[1])

    # helper to clamp move
    best_dx = 0
    best_dy = 0

    def distance(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    target = None

    # 1) Try nearest resource if available
    if isinstance(resources, list) and resources:
        # resources may be list of positions
        nearest = None
        nearest_dist = 10**9
        for r in resources:
            if isinstance(r, (list, tuple)) and len(r) >= 2:
                d = distance((ox_x, ox_y), (int(r[0]), int(r[1])))
                if d < nearest_dist:
                    nearest_dist = d
                    nearest = (int(r[0]), int(r[1]))
        if nearest is not None:
            target = nearest

    # 2) If no resources, try goal_pos
    if target is None and isinstance(gx, (list, tuple)) and len(gx) >= 2:
        target = (int(gx[0]), int(gx[1]))
    elif gx is not None:
        try:
            target = (int(gx[0]), int(gx[1]))
        except Exception:
            target = None

    # 3) If no target yet, move toward territory center
    if target is None and isinstance(territory_center, (list, tuple)) and len(territory_center) >= 2:
        target = (int(territory_center[0]), int(territory_center[1]))
    elif target is None:
        target = (ox_x, ox_y)

    # Determine step toward target with constraint of -1..1
    tx, ty = target
    dx = 0
    dy = 0
    if tx > ox_x:
        dx = 1
    elif tx < ox_x:
        dx = -1
    else:
        dx = 0

    if ty > ox_y:
        dy = 1
    elif ty < ox_y:
        dy = -1
    else:
        dy = 0

    # Clip to -1..1 (already)
    return [dx, dy]

